@startuml
class Factory {
  +id : int
}

class Machine {
  +serialNumber : string
  +make : string
  +model : string
  +purchaseDate : date
}

class Worker {
  +id : int
  +firstName : string
  +lastName : string
  +birthDate : date
  +address : string
  +skills : string[]
}

class ProductType {
  +id : int
  +name : string
  +weight : float
  +material : string
}

class Client {
  +id : int
  +name : string
  +address : string
  +phoneNumber : string
  +contactPerson : string
}

class PurchaseOrder {
  +orderNumber : string
  +dateMade : date
  +expectedDeliveryDate : date
  +actualDeliveryDate : date
}

class OrderLine {
  +quantity : int
}

Factory "1" *-- "*" Machine
Machine "1" -- "*" ProductType
Machine "1..*" -- "1..*" Worker

Client "1" -- "*" PurchaseOrder : issues
PurchaseOrder "1" *-- "1..*" OrderLine
OrderLine "*" -- "1" ProductType
@enduml

